('a2453480-1183-a695-2334-50abb70606f4', '51d08657-1487-ad79-b111-8c7eea1640e6', 1, NULL, 'Imported package content', 'Imported from 08 Days Rajasthan Tour for Website.docx', 'manual'::revision_save_type, '{"header": {"title": "08 Days Udaipur-Mount Abu-Jodhpur& Jaisalmer Tour Package", "subtitle": "Udaipur-Mount Abu-Jodhpur& Jaisalmer", "tour_code": "DR056", "duration_label": "07 Night / 08 Days", "alternate_titles": []}, "client": {"title": "Mr", "client_name": "Website Package", "email": null, "email2": null, "phone": null, "adults": 2, "children_5_12": 0, "children_below_5": 0, "rooms": 1, "extra_beds": 0, "travel_date": null, "food_preference": null, "special_requests": null}, "days": [{"day_uuid": "1c04f5fa-8805-5151-4533-09eb29464f95", "day_number": 1, "day_title": "Arrival in Udaipur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Udaipur, where royal palaces reflect on peaceful lakes, echoing tales of timeless beauty and charm. Upon arrival at Udaipur Railway Station/Airport, our representative will warmly welcome you and assist you to your hotel. Rest of the day is free for you to relax and unwind.\nIn the evening, enjoy a serene Boat Ride on Lake Pichola at sunset.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Udaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": false, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "9ed25e69-e959-3dd8-f6d6-50dde7649fe6", "day_number": 2, "day_title": "Udaipur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, start with a comprehensive tour of Udaipur:\nCity Palace - Royal heritage unfolds here.\nJagdish Temple - Architectural marvel of Udaipur.\nBhartiya Lok Kala Mandal - Cultural treasures on display.\nPratap Smarak - Tribute to courageous history.\nShilp Gram - Artisan village charm.\nBagore ki Haveli - Echoes of royal life.\nSaheliyon ki Bari-Peaceful Garden retreat.\nOvernight stay at a hotel in Udaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Udaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "5aec1e89-885f-e043-64b0-446698047454", "day_number": 3, "day_title": "Udaipur – Mount Abu Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Mount Abu, a calm retreat Rajasthani hill, where ancient temples and scenic vistas consists of textile and spiritual comfort.\nAfter breakfast, proceed to Mount Abu. Check in at the hotel and visit:\nDelwara Temple - Lovely Jain craftsmanship.\nVedi Temple - Calm spiritual refuge.\nNakki Lake - Picturesque natural beauty.\nSunset Point - Spectacular beautiful views.\nTod Rock - Scenic rock formations.\nGuru Shikhar - Highest peak adventure.\nAchalgarh Mahadev - Ancient temple fort.\nBrahma Kumari Ashram - Spiritual sanctuary.\nOvernight stay at a hotel in Mount Abu.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Mount Abu", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "f646df5e-b05e-33f2-4e73-e458ff5d21e7", "day_number": 4, "day_title": "Mount Abu - Ranakpur - Jodhpur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Jodhpur, the ''Blue City'', where majestic forts rise from the desert. After breakfast, head to Jodhpur with a stopover at Ranakpur Jain Temples, renowned for their architectural brilliance and religious significance. Continue to Jodhpur and check in at the hotel.\nOvernight stay at a hotel in Jodhpur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Mount Abu", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "5db935f4-d52b-b5e1-f921-a9108c93627a", "day_number": 5, "day_title": "Jodhpur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Begin your beautiful day with a visit to:\nUmmaid Bhawan Palace Museum - Luxurious history awaits.\nJaswant Thada - Marble memorial peace.\nMehrangarh Fort - Majestic stronghold of Rajasthan.\nClock Tower & Markets - Vibrant local culture hub.\nOvernight stay at a hotel in Jodhpur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jodhpur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "7f49294c-dfbd-c898-b654-dd7a879cda17", "day_number": 6, "day_title": "Jodhpur - Jaisalmer", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Jaisalmer, the ''Golden City'', where ancient sandstone fortresses shine under the desert sun, a mirage of history and culture. After breakfast, drive to Jaisalmer. Check in at the hotel and freshen up before visiting:\nWar Museum - Military history insights.\nGadisar Lake - Peaceful oasis charm.\nVyas Chhatri - Architectural marvel viewpoint.\nOvernight stay at a hotel in Jaisalmer.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaisalmer", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "161a2d38-b6c8-8a85-4cc7-bdb13cbdee3b", "day_number": 7, "day_title": "Sightseeing & Jaisalmer Desert", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Explore the highlights of Jaisalmer:\nJaisalmer Fort & Palaces - Golden city''s crown jewel.\nJain Temples - Complex sandstone craftsmanship.\nPatwon ki Haveli - Historical merchant mansion.\nSalim Singh ki Haveli - Unique architectural refinement.\nNathmal ki Haveli - Fusion of local styles.\nLater, enjoy a unique overnight stay in tents at a Desert Camp amidst dunes with cultural programs, camel rides, bonfire, sunset views, and dinner.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaisalmer", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "3d1fa110-b59c-f269-1a7f-c753f100fd8c", "day_number": 8, "day_title": "Jaisalmer Departure", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, check out from the Desert Camp and visit:\nLodhurva - Sign of Ancient charm.\nAmar Sagar - Serene oasis peacefulness.\nKuldhara - Haunted village echoes.\nYou will then be transferred to Jaisalmer Railway Station/Airport for your departure.\n(The Tour Ends)", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaisalmer", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": false, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}], "inclusions": ["Daily breakfast", "Air-conditioned car for transportation throughout the journey", "Driver allowance, fuel, parking fees, and all applicable taxes", "Accommodation in 3-star hotels", "Camel Ride, Bonfire, Hi-Tea, Cultural Programs & Vegetarian Dinner at Desert Camp", "Government-approved tourist guide service for sightseeing in Udaipur", "Complimentary accommodation for children below 5 years of age"], "exclusions": ["Meals other than those specified in the inclusions", "Personal expenses such as tips, telephone calls, and laundry", "Entrance fees to monuments and attractions", "Camera fees", "Any tickets for trains, flights, or buses", "Travel insurance"], "inclusion_items": [{"id": "aaf0b44a-6576-fcb8-3379-109c84a855d2", "title": "Daily breakfast", "description": "", "images": []}, {"id": "3ae3fa55-ef54-e95c-674f-ecaf3f23769c", "title": "Air-conditioned car for transportation throughout the journey", "description": "", "images": []}, {"id": "269cf080-607a-c1c4-6e71-b28cd78ebd62", "title": "Driver allowance, fuel, parking fees, and all applicable taxes", "description": "", "images": []}, {"id": "952bf12e-76f8-b627-554d-0242d20dcce0", "title": "Accommodation in 3-star h