('7629f9b2-af36-99bc-ecdc-5674f84fe232', 'f793d115-3003-33f1-ffae-310170658f5e', 1, NULL, 'Imported package content', 'Imported from 09 Days Rajasthan Tour for Website - Updated.docx', 'manual'::revision_save_type, '{"header": {"title": "09 Days Udaipur-Mount Abu-Jodhpur-Jaisalmer- Bikaner Tour Package", "subtitle": "Udaipur-Mount Abu-Jodhpur-Jaisalmer- Bikaner", "tour_code": "DR060", "duration_label": "08 Night / 09 Days", "alternate_titles": []}, "client": {"title": "Mr", "client_name": "Website Package", "email": null, "email2": null, "phone": null, "adults": 2, "children_5_12": 0, "children_below_5": 0, "rooms": 1, "extra_beds": 0, "travel_date": null, "food_preference": null, "special_requests": null}, "days": [{"day_uuid": "45f6a4cb-28a1-cfa5-566e-b7ec1099f037", "day_number": 1, "day_title": "Arrival in Udaipur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Udaipur also known as the \"City of Lakes,\" it enchants with its serene waters, grand palaces, and romantic atmosphere. Visit the exquisite City Palace and enjoy a boat ride on Lake Pichola.\nUpon arrival at Udaipur Railway Station/Airport, our representative will warmly greet you and transfer you to your hotel. Spend the rest of the day relaxing at your hotel.\nIn the evening, we will visit Pichola lake.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Udaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": false, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_